// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("lists the next statuses", () -> {
        eq(Status.NEW.next(), Set.of(Status.PAID, Status.CANCELLED));
        eq(Status.SHIPPED.next(), Set.of(Status.DELIVERED));
    });
    test("allows the happy path", () ->
        eq(Status.NEW.moveTo(Status.PAID).moveTo(Status.SHIPPED).moveTo(Status.DELIVERED), Status.DELIVERED));
    test("can cancel before shipping", () -> {
        eq(Status.NEW.canMoveTo(Status.CANCELLED), true);
        eq(Status.PAID.canMoveTo(Status.CANCELLED), true);
    });
    test("cannot cancel once shipped", () -> eq(Status.SHIPPED.canMoveTo(Status.CANCELLED), false));
    test("cannot go backwards or stay put", () -> {
        eq(Status.SHIPPED.canMoveTo(Status.PAID), false);
        eq(Status.PAID.canMoveTo(Status.PAID), false);
    });
    test("an illegal move names both statuses", () ->
        raises(IllegalStateException.class, () -> Status.SHIPPED.moveTo(Status.PAID), "SHIPPED -> PAID"));
    test("delivered and cancelled are final", () -> {
        eq(Status.DELIVERED.isFinal(), true);
        eq(Status.CANCELLED.isFinal(), true);
        eq(Status.NEW.isFinal(), false);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("deposits and withdraws", () -> {
        var acct = funded(100);
        acct.withdraw(30);
        eq(acct.balance(), 70);
    });
    test("never goes negative", () -> {
        var acct = funded(100);
        raises(IllegalStateException.class, () -> acct.withdraw(101));
        eq(acct.balance(), 100);
    });
    test("a frozen account refuses withdrawals but takes deposits", () -> {
        var acct = funded(100);
        acct.freeze();
        raises(IllegalStateException.class, () -> acct.withdraw(10));
        acct.deposit(5);
        eq(acct.balance(), 105);
        acct.unfreeze();
        acct.withdraw(5);
        eq(acct.balance(), 100);
    });
    test("only an empty account can close", () -> {
        var acct = funded(100);
        raises(IllegalStateException.class, acct::close);
        eq(acct.isClosed(), false);
        acct.withdraw(100);
        acct.close();
        eq(acct.isClosed(), true);
    });
    test("a closed account refuses everything", () -> {
        var acct = new Account();
        acct.close();
        raises(IllegalStateException.class, () -> acct.deposit(1));
        raises(IllegalStateException.class, () -> acct.withdraw(1));
        raises(IllegalStateException.class, acct::freeze);
        raises(IllegalStateException.class, acct::close);
    });
    test("bad amounts are argument errors", () -> {
        var acct = funded(100);
        raises(IllegalArgumentException.class, () -> acct.deposit(0));
        raises(IllegalArgumentException.class, () -> acct.withdraw(-1));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("reserves a whole order", () -> {
        var inv = shop();
        eq(inv.reserve(Map.of("TEA", 2, "CAKE", 1)), true);
        eq(inv.available("TEA"), 3);
        eq(inv.available("CAKE"), 0);
    });
    test("a short order changes nothing", () -> {
        var inv = shop();
        inv.reserve(Map.of("CAKE", 1));
        eq(inv.reserve(Map.of("TEA", 1, "CAKE", 1)), false);
        eq(inv.available("TEA"), 5);
    });
    test("an unknown sku has nothing available", () -> {
        var inv = shop();
        eq(inv.available("COFFEE"), 0);
        eq(inv.reserve(Map.of("TEA", 1, "COFFEE", 1)), false);
        eq(inv.available("TEA"), 5);
    });
    test("can reserve right down to zero", () -> {
        var inv = shop();
        eq(inv.reserve(Map.of("TEA", 5)), true);
        eq(inv.reserve(Map.of("TEA", 1)), false);
    });
    test("release puts stock back", () -> {
        var inv = shop();
        inv.reserve(Map.of("TEA", 4));
        inv.release(Map.of("TEA", 4));
        eq(inv.available("TEA"), 5);
    });
    test("a bad quantity is refused before anything changes", () -> {
        var inv = shop();
        raises(IllegalArgumentException.class, () -> inv.reserve(Map.of("TEA", 1, "CAKE", 0)));
        eq(inv.available("TEA"), 5);
        raises(IllegalArgumentException.class, () -> inv.release(Map.of("TEA", -2)));
    });
    test("keeps its own copy of the starting stock", () -> {
        var start = new HashMap<>(Map.of("TEA", 5));
        var inv = new Inventory(start);
        start.put("TEA", 0);
        inv.reserve(Map.of("TEA", 1));
        eq(inv.available("TEA"), 4);
        eq(start.get("TEA"), 0);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("a perfect score", () -> eq(score(QUIZ, Map.of("q1", 2, "q2", 0, "q3", 1)), new Score(6, 6, List.of())));
    test("wrong answers earn nothing and are listed", () ->
        eq(score(QUIZ, Map.of("q1", 2, "q2", 1, "q3", 1)), new Score(3, 6, List.of("q2"))));
    test("unanswered questions are missed too, in quiz order", () ->
        eq(score(QUIZ, Map.of("q2", 0)), new Score(3, 6, List.of("q1", "q3"))));
    test("an answer to an unknown question is an error", () ->
        raises(IllegalArgumentException.class, () -> score(QUIZ, Map.of("q1", 2, "q9", 0)), "q9"));
    test("percent rounds to a whole number", () -> {
        eq(percent(new Score(1, 4, List.of())), 25);
        eq(percent(new Score(1, 3, List.of())), 33);
        eq(percent(new Score(2, 3, List.of())), 67);
    });
    test("percent rounds a half up", () -> eq(percent(new Score(1, 8, List.of())), 13));
    test("percent of an empty quiz is zero", () -> eq(percent(score(List.of(), Map.of())), 0));
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("a new task is TODO with no history", () -> {
        var t = new Task("write report");
        eq(t.state(), State.TODO);
        eq(t.history(), List.of());
    });
    test("requires a title", () -> raises(IllegalArgumentException.class, () -> new Task("  ")));
    test("records every move", () -> {
        var t = new Task("write report");
        t.start();
        t.finish();
        t.reopen();
        eq(t.history(), List.of("TODO -> DOING", "DOING -> DONE", "DONE -> TODO"));
        eq(t.state(), State.TODO);
    });
    test("cannot skip a step", () -> {
        var t = new Task("write report");
        raises(IllegalStateException.class, t::finish, "TODO");
        raises(IllegalStateException.class, t::reopen);
    });
    test("a refused move records nothing", () -> {
        var t = new Task("write report");
        t.start();
        raises(IllegalStateException.class, t::start);
        eq(t.history(), List.of("TODO -> DOING"));
    });
    test("history is read-only", () -> {
        var t = new Task("write report");
        t.start();
        raises(UnsupportedOperationException.class, () -> t.history().clear());
    });
    test("counts reopens", () -> {
        var t = new Task("write report");
        for (int i = 0; i < 2; i++) {
            t.start();
            t.finish();
            t.reopen();
        }
        eq(t.timesReopened(), 2);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("charges a payment", () -> {
        var p = withBalance(500);
        eq(p.apply(new Payment("pay-1", "acct", 300)), "charged pay-1");
        eq(p.balance("acct"), 200);
    });
    test("a duplicate delivery charges nothing", () -> {
        var p = withBalance(500);
        p.apply(new Payment("pay-1", "acct", 300));
        eq(p.apply(new Payment("pay-1", "acct", 300)), "duplicate pay-1");
        eq(p.balance("acct"), 200);
    });
    test("different ids are different payments", () -> {
        var p = withBalance(500);
        p.apply(new Payment("pay-1", "acct", 100));
        eq(p.apply(new Payment("pay-2", "acct", 100)), "charged pay-2");
        eq(p.balance("acct"), 300);
    });
    test("declines without enough money and changes nothing", () -> {
        var p = withBalance(500);
        eq(p.apply(new Payment("pay-9", "acct", 900)), "declined pay-9");
        eq(p.balance("acct"), 500);
    });
    test("a declined id can be retried after a top-up", () -> {
        var p = withBalance(500);
        p.apply(new Payment("pay-9", "acct", 900));
        p.topUp("acct", 500);
        eq(p.apply(new Payment("pay-9", "acct", 900)), "charged pay-9");
        eq(p.balance("acct"), 100);
    });
    test("refuses unknown accounts and bad amounts", () -> {
        var p = withBalance(500);
        raises(IllegalArgumentException.class, () -> p.apply(new Payment("x", "nobody", 1)));
        raises(IllegalArgumentException.class, () -> p.apply(new Payment("x", "acct", 0)));
    });
    test("can spend the balance exactly", () -> {
        var p = withBalance(500);
        eq(p.apply(new Payment("all", "acct", 500)), "charged all");
        eq(p.balance("acct"), 0);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

